def experiment(inputs):
    import random
    def get_preference_state(seed):
        random.seed(seed)
        state = 0.5
        for i in range(100):
            noise = random.uniform(-0.1, 0.1)
            state = min(1.0, max(0.0, state + noise))
        return state
    agent_a = get_preference_state(inputs['seeds'][0])
    agent_b = get_preference_state(inputs['seeds'][1])
    return {'divergence': abs(agent_a - agent_b)}

